function score(sequence, candidates, dataset, lambda):
    base = dataset.model.predict(sequence, candidates)
    recent = last_nonpadding_items(sequence, limit=3)
    transition = recency_weighted_smoothed_transition_scores(recent, candidates)
    return standardize(base) + lambda * standardize(transition)

